import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"Ceph Performance Meeting 2023-03-09","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-03-09","date":"2023-03-09T00:00:00.000Z","updated":"2023-03-15T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PR审查","蓝店缓冲IO"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-03-09.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-03-09.md","lastUpdated":1780460162000}'),a={name:"posts/2023/Ceph_Performance_Meeting_2023-03-09.md"};function i(n,e,s,u,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2023年3月9日<br><strong>参会人员：</strong> [参会人员列表]<br><strong>会议主持：</strong> [主持人姓名]</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li>主持人因与Josh讨论碎片整理而迟到。</li><li>讨论了本周的两个新PR，均与Crimson Suite相关。</li><li>讨论了更新PR，包括qat batch PR、Corey的PR（roxdb迭代器边界）和Igor的PR（预取缓冲区重置）。</li><li>讨论了Blue Store buffered IO的性能问题，特别是与roxdb的交互和预取缓冲区的使用。</li><li>讨论了CBT的一个PR，关于禁用现有结果目录检查的问题。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>新PR讨论</strong></p><ul><li>Matan的PR：修复了Crimson性能测试中的collect all安装问题。</li><li>Intel开发者的PR：增加了细粒度缓存，并提供了基准测试结果。</li></ul></li><li><p><strong>更新PR讨论</strong></p><ul><li>qat batch PR：来自Intel，有一些额外的审查。</li><li>Corey的PR：关于roxdb迭代器边界，有一些新的修复。</li><li>Igor的PR：关于预取缓冲区的重置问题，可能有助于改善roxdb的预取行为。</li></ul></li><li><p><strong>Blue Store Buffered IO问题</strong></p><ul><li>讨论了是否可以在禁用Blue Store buffered IO的同时，通过BlueFS层进行预取缓存。</li><li>讨论了roxdb的块缓存问题，以及是否可以通过改进BlueFS层来解决。</li></ul></li><li><p><strong>CBT PR讨论</strong></p><ul><li>讨论了一个关于禁用现有结果目录检查的PR，目的是防止重复运行测试。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>对于新PR和更新PR，将继续进行审查和测试。</li><li>对于Blue Store buffered IO问题，将继续探索在BlueFS层进行预取缓存的可能性。</li><li>对于CBT PR，将寻找更细致的解决方案，而不是完全禁用现有目录检查。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查和测试本周的新PR和更新PR。</li><li>进一步研究和测试Blue Store buffered IO的性能问题。</li><li>与Nissan跟进CBT PR的问题，寻找更细致的解决方案。</li></ul><p><strong>会议结束时间：</strong> [具体时间]<br><strong>下次会议预告：</strong> [具体日期]</p><p><strong>会议记录人：</strong> [记录人姓名]<br><strong>审核人：</strong> [审核人姓名]</p><p><strong>备注：</strong> 会议中提到的技术细节和讨论点需要进一步的技术验证和代码审查。</p>',13)])])}const g=l(a,[["render",i]]);export{P as __pageData,g as default};
